<section id="gioi-thieu" class="v2-detail-section" tabindex="-1"><h2>Giới thiệu</h2><div class="v2-editorial"><?php echo trim($item['content'])?vibelab_v2_detail_content($item):'<p>Chưa có giới thiệu chi tiết. Hãy đọc mô tả, điều kiện và nguồn trước khi lựa chọn.</p>'; ?></div></section>
